const qs=[
  ["plan headings","rg -n '<h[1-3]|quarant|failure|stale|telemetry|VoiceOver|keyboard|motion|locali|notif|cancel|redact|credential|state|restart|crash|privacy' artifacts/msw-menu-bar-app-plan.html"],
  ["msw behavior","rg -n 'quarant|trap|SIG|INT|TERM|cancel|cleanup|status_cmd|cmd_status|metrics|github_status|assert_not_quarantined|quarantine_workspace|start_box|stop_box|restart|check|kill|token|credential|background|wait' bin/msw"],
  ["tests quarantine","rg -n 'quarant|SIGKILL|interrupt|lock|cancel|stop fail|status fail|taint|cleanup|token.*output|secret' tests/test_suite.py"],
  ["docs detail","rg -n 'quarant|failure|failed|interrupt|token|secret|stop|restart|status|metrics|Keychain|lock' docs/*.md README.md"]
];
const rs=await Promise.all(qs.map(([n,c])=>tools.exec_command({cmd:c,workdir:"/Users/polarzero/code/projects/microsandbox-workspaces",yield_time_ms:10000,max_output_tokens:30000})));
rs.forEach((r,i)=>text(`### ${qs[i][0]}\n${r.output}`));

const specs=[
["plan","sed -n '108,306p' artifacts/msw-menu-bar-app-plan.html"],
["quarantine lifecycle","sed -n '242,390p' bin/msw"],
["start stop status","sed -n '510,585p' bin/msw"],
["github transaction","sed -n '860,1035p' bin/msw"],
["github status remove","sed -n '1290,1505p' bin/msw"],
["tests quarantine A","sed -n '518,885p' tests/test_suite.py"],
["tests quarantine B","sed -n '885,930p' tests/test_suite.py"],
["github docs","sed -n '82,180p' docs/GITHUB-SETUP.md"],
["setup operations","sed -n '236,320p' docs/SETUP-GUIDE.md"]
];
const rs=await Promise.all(specs.map(([n,c])=>tools.exec_command({cmd:c,workdir:"/Users/polarzero/code/projects/microsandbox-workspaces",yield_time_ms:10000,max_output_tokens:50000})));
rs.forEach((r,i)=>text(`### ${specs[i][0]}\n${r.output}`));

const chunks=[
["plan contract","sed -n '231,305p' artifacts/msw-menu-bar-app-plan.html"],
["quarantine","sed -n '242,346p' bin/msw"],
["state operations","sed -n '346,385p' bin/msw; sed -n '530,580p' bin/msw"],
["github setup remove names","rg -n '^github_|^cmd_github|setup_transaction|quarantine_workspace|clear_quarantine' bin/msw"],
["github impl","sed -n '880,1275p' bin/msw"],
["remove impl","sed -n '1275,1455p' bin/msw"]
];
const rs=await Promise.all(chunks.map(([n,c])=>tools.exec_command({cmd:c,workdir:"/Users/polarzero/code/projects/microsandbox-workspaces",yield_time_ms:10000,max_output_tokens:35000})));
rs.forEach((r,i)=>text(`### ${chunks[i][0]}\n${r.output}`));

const r=await tools.web__run({search_query:[
 {q:"site:developer.apple.com/documentation/swiftui accessibilityReduceMotion accessibilityDifferentiateWithoutColor macOS"},
 {q:"site:developer.apple.com/documentation/accessibility macOS VoiceOver keyboard accessibility SwiftUI"},
 {q:"site:developer.apple.com/documentation/usernotifications requestAuthorization notifications macOS"},
 {q:"site:developer.apple.com/documentation/foundation/process terminate interrupt macOS"}
],response_length:"long"}); text(r)
